//! Integration tests for the monthly key limits: the 429 gate in the proxy
//! auth path, the in-memory verdict behind it, the audit row a rejection
//! leaves, the flood-cap interaction and the documented edges (a fresh
//! process, a channel that cannot be priced, a month rollover).
//!
//! Every stage is deterministic: the verdict is produced by calling
//! [`hydra::usage::recompute`] directly instead of waiting for the detached
//! recompute of a logged response, and the spend under test is seeded as a
//! `request_logs` row rather than generated by a real upstream call.

mod common;

use std::time::{Duration, Instant};

use axum::body::{to_bytes, Body};
use axum::http::{Request, StatusCode};
use base64::Engine as _;
use serde_json::{json, Value};
use sqlx::SqlitePool;
use tower::ServiceExt;

use common::{
    fixed_response_router, spawn_hydra_with_connect_info, spawn_upstream, test_app,
    test_app_with_flood, test_pool, within, Recorder, UPSTREAM_KEY,
};
use hydra::db::channels::{self, NewChannel};
use hydra::db::keys::{self, NewKey};
use hydra::db::request_logs::{self, NewRequestLog};
use hydra::db::Db;
use hydra::http::{router, AppState};
use hydra::month::Month;
use hydra::prices::ModelPrices;

/// The only model the limitable test channel serves.
const CHAT_MODEL: &str = "gpt-4o";

/// What one seeded request costs, through the pinned formula: 1000 prompt
/// tokens with 400 of them cached (600 uncached at 2.50 plus 400 cached at
/// 1.25) and 200 completion tokens at 10.00 USD per 1M, that is
/// 1500 + 500 + 2000 micro-USD.
const REQUEST_COST: i64 = 4_000;

/// A non-streaming upstream completion, so a request that passes the gate
/// gets a real 200.
const COMPLETION: &str = r#"{"id":"chatcmpl-1","object":"chat.completion","model":"gpt-4o","choices":[{"index":0,"message":{"role":"assistant","content":"hi"},"finish_reason":"stop"}],"usage":{"prompt_tokens":10,"completion_tokens":2}}"#;

fn db(pool: &SqlitePool) -> Db {
    Db::from(pool.clone())
}

/// The price table the limitable channel carries: every whitelisted model
/// priced in all four dimensions.
fn price_table() -> ModelPrices {
    ModelPrices::from_usd_json(&json!({
        "gpt-4o": {
            "input": "2.50",
            "output": "10.00",
            "cached_input": "1.25",
            "cached_output": "5.00"
        }
    }))
    .unwrap()
}

/// A channel a monthly limit can be enforced against: enabled, whitelisted
/// and fully priced.
async fn seed_limitable_channel(pool: &SqlitePool, base_url: &str) -> i64 {
    let priced = within(channels::create_with_prices(
        &db(pool),
        &NewChannel {
            name: "limitable".to_string(),
            base_url: base_url.to_string(),
            api_key: UPSTREAM_KEY.to_string(),
            allowed_models: Some(vec![CHAT_MODEL.to_string()]),
        },
        Some(&price_table()),
    ))
    .await
    .unwrap();
    assert!(priced.limitable(), "the seeded channel must be limitable");
    priced.channel.id
}

/// A channel whose limit can never be enforced: no whitelist, so no finite
/// model set to price.
async fn seed_unlimitable_channel(pool: &SqlitePool, base_url: &str) -> i64 {
    within(channels::create(
        &db(pool),
        &NewChannel {
            name: "unlimitable".to_string(),
            base_url: base_url.to_string(),
            api_key: UPSTREAM_KEY.to_string(),
            allowed_models: None,
        },
    ))
    .await
    .unwrap()
    .id
}

/// A key bound to `channel_id` with an optional monthly limit; returns the
/// row id and the plaintext key to authenticate with.
async fn seed_limited_key(pool: &SqlitePool, channel_id: i64, limit: Option<i64>) -> (i64, String) {
    let generated = hydra::keys::generate();
    let key = within(keys::create(
        &db(pool),
        &NewKey {
            key_hash: generated.key_hash,
            display_prefix: generated.display_prefix,
            name: None,
            channel_id,
            monthly_limit_micro_usd: limit,
        },
    ))
    .await
    .unwrap();
    (key.id, generated.full)
}

/// One month-to-date request log row for the key.
fn usage_row(key_id: i64, channel_id: i64) -> NewRequestLog {
    NewRequestLog {
        api_key_id: Some(key_id),
        channel_id: Some(channel_id),
        model: Some(CHAT_MODEL.to_string()),
        status: Some(200),
        prompt_tokens: Some(1000),
        completion_tokens: Some(200),
        cached_input_tokens: Some(400),
        cached_output_tokens: None,
        duration_ms: 1,
        request_body: None,
        response_body: None,
        error: None,
        client_ip: None,
    }
}

/// Puts one request's usage in the log at an explicit instant.
async fn log_usage_at(pool: &SqlitePool, key_id: i64, channel_id: i64, at: &str) {
    within(request_logs::insert_at(
        &db(pool),
        &usage_row(key_id, channel_id),
        at,
    ))
    .await
    .unwrap();
}

/// Puts one request's usage in the log as of now.
async fn log_usage_now(pool: &SqlitePool, key_id: i64, channel_id: i64) {
    within(request_logs::insert(
        &db(pool),
        &usage_row(key_id, channel_id),
    ))
    .await
    .unwrap();
}

/// The verdict the detached path would compute, produced deterministically.
async fn recompute(state: &AppState, pool: &SqlitePool, key_id: i64) {
    within(hydra::usage::recompute(
        &db(pool),
        &state.limit_flags,
        key_id,
    ))
    .await
    .unwrap();
}

fn chat_request(key: &str) -> Request<Body> {
    Request::builder()
        .method("POST")
        .uri("/v1/chat/completions")
        .header("authorization", format!("Bearer {key}"))
        .header("content-type", "application/json")
        .body(Body::from(
            json!({ "model": CHAT_MODEL, "messages": [{ "role": "user", "content": "hi" }] })
                .to_string(),
        ))
        .unwrap()
}

/// The same request on the second proxied POST surface, which runs the same
/// auth extractor and therefore the same limit gate.
fn responses_request(key: &str) -> Request<Body> {
    Request::builder()
        .method("POST")
        .uri("/v1/responses")
        .header("authorization", format!("Bearer {key}"))
        .header("content-type", "application/json")
        .body(Body::from(
            json!({ "model": CHAT_MODEL, "input": [{ "role": "user", "content": "hi" }] })
                .to_string(),
        ))
        .unwrap()
}

async fn send(state: &AppState, request: Request<Body>) -> (StatusCode, Value) {
    let response = within(router(state.clone()).oneshot(request))
        .await
        .unwrap();
    let status = response.status();
    let bytes = within(to_bytes(response.into_body(), usize::MAX))
        .await
        .unwrap();
    let body = if bytes.is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap()
    };
    (status, body)
}

async fn chat(state: &AppState, key: &str) -> (StatusCode, Value) {
    send(state, chat_request(key)).await
}

fn models_request(key: &str) -> Request<Body> {
    Request::builder()
        .method("GET")
        .uri("/v1/models")
        .header("authorization", format!("Bearer {key}"))
        .body(Body::empty())
        .unwrap()
}

fn auth_header() -> String {
    format!(
        "Basic {}",
        base64::engine::general_purpose::STANDARD.encode("admin:secret")
    )
}

/// Polls the log until a row matching `predicate` is visible; the inserts run
/// detached.
async fn wait_for_row(
    pool: &SqlitePool,
    predicate: impl Fn(&request_logs::RequestLog) -> bool,
) -> request_logs::RequestLog {
    let filters = request_logs::LogFilters {
        key_id: None,
        channel_id: None,
        model: None,
        status_class: None,
        from: None,
        to: None,
        page: 1,
        page_size: 50,
    };
    let deadline = Instant::now() + common::TEST_TIMEOUT;
    loop {
        let (rows, _) = within(request_logs::list(&db(pool), &filters))
            .await
            .unwrap();
        if let Some(row) = rows.into_iter().find(|row| predicate(row)) {
            return row;
        }
        assert!(Instant::now() < deadline, "expected log row never landed");
        tokio::time::sleep(Duration::from_millis(25)).await;
    }
}

/// A mock upstream answering every chat and models call with a fixed body.
async fn upstream() -> String {
    spawn_upstream(fixed_response_router(
        Recorder::default(),
        StatusCode::OK,
        "application/json",
        COMPLETION.as_bytes().to_vec(),
    ))
    .await
}

#[tokio::test]
async fn an_over_budget_key_is_rejected_with_the_monthly_limit_error() {
    let pool = test_pool().await;
    let channel_id = seed_limitable_channel(&pool, &upstream().await).await;
    // One request already costs more than this budget.
    let (key_id, key) = seed_limited_key(&pool, channel_id, Some(REQUEST_COST - 1)).await;
    let state = test_app(pool.clone());
    log_usage_now(&pool, key_id, channel_id).await;
    recompute(&state, &pool, key_id).await;

    let (status, body) = chat(&state, &key).await;
    assert_eq!(status, StatusCode::TOO_MANY_REQUESTS);
    assert_eq!(
        body,
        json!({
            "error": {
                "message": "Monthly limit reached",
                "type": "rate_limit_error",
                "code": Value::Null
            }
        })
    );
}

#[tokio::test]
async fn a_key_below_its_limit_still_serves_traffic() {
    let pool = test_pool().await;
    let channel_id = seed_limitable_channel(&pool, &upstream().await).await;
    // One micro-USD above the seeded spend: the budget is not spent yet.
    let (key_id, key) = seed_limited_key(&pool, channel_id, Some(REQUEST_COST + 1)).await;
    let state = test_app(pool.clone());
    log_usage_now(&pool, key_id, channel_id).await;
    recompute(&state, &pool, key_id).await;

    let (status, _) = chat(&state, &key).await;
    assert_eq!(status, StatusCode::OK);
}

#[tokio::test]
async fn raising_the_limit_through_the_admin_api_lets_the_next_request_through() {
    let pool = test_pool().await;
    let channel_id = seed_limitable_channel(&pool, &upstream().await).await;
    let (key_id, key) = seed_limited_key(&pool, channel_id, Some(REQUEST_COST - 1)).await;
    let state = test_app(pool.clone());
    log_usage_now(&pool, key_id, channel_id).await;
    recompute(&state, &pool, key_id).await;
    let (status, _) = chat(&state, &key).await;
    assert_eq!(status, StatusCode::TOO_MANY_REQUESTS);

    // The admin PATCH goes through `mutate_key`, which drops the verdict.
    let request = Request::builder()
        .method("PATCH")
        .uri(format!("/admin/keys/{key_id}"))
        .header("authorization", auth_header())
        .header("content-type", "application/json")
        .body(Body::from(
            json!({ "monthly_limit_usd": "50.00" }).to_string(),
        ))
        .unwrap();
    let response = within(router(state.clone()).oneshot(request))
        .await
        .unwrap();
    assert_eq!(response.status(), StatusCode::OK);

    let (status, _) = chat(&state, &key).await;
    assert_eq!(
        status,
        StatusCode::OK,
        "a raised limit must stop gating the key"
    );
}

#[tokio::test]
async fn clearing_the_limit_through_the_admin_api_lets_the_next_request_through() {
    let pool = test_pool().await;
    let channel_id = seed_limitable_channel(&pool, &upstream().await).await;
    let (key_id, key) = seed_limited_key(&pool, channel_id, Some(1)).await;
    let state = test_app(pool.clone());
    log_usage_now(&pool, key_id, channel_id).await;
    recompute(&state, &pool, key_id).await;
    let (status, _) = chat(&state, &key).await;
    assert_eq!(status, StatusCode::TOO_MANY_REQUESTS);

    let request = Request::builder()
        .method("PATCH")
        .uri(format!("/admin/keys/{key_id}"))
        .header("authorization", auth_header())
        .header("content-type", "application/json")
        .body(Body::from(json!({ "monthly_limit_usd": null }).to_string()))
        .unwrap();
    let response = within(router(state.clone()).oneshot(request))
        .await
        .unwrap();
    assert_eq!(response.status(), StatusCode::OK);

    let (status, _) = chat(&state, &key).await;
    assert_eq!(status, StatusCode::OK, "an unlimited key is never gated");
}

#[tokio::test]
async fn the_first_request_of_a_fresh_process_passes_before_any_verdict_exists() {
    let pool = test_pool().await;
    let channel_id = seed_limitable_channel(&pool, &upstream().await).await;
    let (key_id, key) = seed_limited_key(&pool, channel_id, Some(1)).await;
    // Over budget in the database, but no verdict was ever computed: the
    // in-memory store starts empty, which is the documented restart
    // behavior.
    log_usage_now(&pool, key_id, channel_id).await;
    let state = test_app(pool.clone());

    let (status, _) = chat(&state, &key).await;
    assert_eq!(status, StatusCode::OK);
}

#[tokio::test]
async fn a_channel_that_cannot_be_priced_leaves_the_stored_limit_unenforced() {
    let pool = test_pool().await;
    let channel_id = seed_unlimitable_channel(&pool, &upstream().await).await;
    let (key_id, key) = seed_limited_key(&pool, channel_id, Some(1)).await;
    let state = test_app(pool.clone());
    log_usage_now(&pool, key_id, channel_id).await;
    recompute(&state, &pool, key_id).await;

    let (status, _) = chat(&state, &key).await;
    assert_eq!(
        status,
        StatusCode::OK,
        "a limit stored against an unpriceable channel is not enforced"
    );
}

#[tokio::test]
async fn a_verdict_from_another_month_does_not_trip_the_gate() {
    let pool = test_pool().await;
    let channel_id = seed_limitable_channel(&pool, &upstream().await).await;
    let (key_id, key) = seed_limited_key(&pool, channel_id, Some(1)).await;
    let state = test_app(pool.clone());
    // Spend from a past month: over budget for that month, invisible to the
    // month-to-date aggregate, and stored under that month's bucket.
    log_usage_at(&pool, key_id, channel_id, "2026-01-15 10:00:00").await;
    recompute(&state, &pool, key_id).await;
    let (status, _) = chat(&state, &key).await;
    assert_eq!(
        status,
        StatusCode::OK,
        "last month's spend is not this month's"
    );

    // An entry keyed to a month that has rolled over must not be read as
    // this month's verdict either.
    let stale = Month::from_parts(2026, 1).unwrap().bucket();
    state.limit_flags.set(key_id, stale, true);
    let (status, _) = chat(&state, &key).await;
    assert_eq!(status, StatusCode::OK);
}

#[tokio::test]
async fn an_over_budget_key_cannot_list_models() {
    let pool = test_pool().await;
    let channel_id = seed_limitable_channel(&pool, &upstream().await).await;
    let (key_id, key) = seed_limited_key(&pool, channel_id, Some(1)).await;
    let state = test_app(pool.clone());
    log_usage_now(&pool, key_id, channel_id).await;
    recompute(&state, &pool, key_id).await;

    let (status, body) = send(&state, models_request(&key)).await;
    assert_eq!(
        status,
        StatusCode::TOO_MANY_REQUESTS,
        "the gate covers /v1/models too: {body}"
    );
    assert_eq!(body["error"]["message"], "Monthly limit reached");
    assert_eq!(body["error"]["type"], "rate_limit_error");
}

#[tokio::test]
async fn an_over_budget_key_cannot_call_responses() {
    let pool = test_pool().await;
    let channel_id = seed_limitable_channel(&pool, &upstream().await).await;
    let (key_id, key) = seed_limited_key(&pool, channel_id, Some(1)).await;
    let state = test_app(pool.clone());
    log_usage_now(&pool, key_id, channel_id).await;
    recompute(&state, &pool, key_id).await;

    let (status, body) = send(&state, responses_request(&key)).await;
    assert_eq!(
        status,
        StatusCode::TOO_MANY_REQUESTS,
        "the gate covers /v1/responses too: {body}"
    );
    assert_eq!(body["error"]["message"], "Monthly limit reached");
    assert_eq!(body["error"]["type"], "rate_limit_error");

    // The rejection is usage of the key that hit its limit, so it keeps the
    // key and lets the per-key reporting stay complete on this surface too.
    let row = wait_for_row(&pool, |row| row.status == Some(429)).await;
    assert_eq!(row.api_key_id, Some(key_id));
    assert_eq!(row.channel_id, Some(channel_id));
    assert_eq!(row.model.as_deref(), Some(CHAT_MODEL));
}

#[tokio::test]
async fn a_limit_rejection_leaves_a_row_for_the_real_key_and_model() {
    let pool = test_pool().await;
    let channel_id = seed_limitable_channel(&pool, &upstream().await).await;
    let (key_id, key) = seed_limited_key(&pool, channel_id, Some(1)).await;
    let state = test_app(pool.clone());
    log_usage_now(&pool, key_id, channel_id).await;
    recompute(&state, &pool, key_id).await;

    let (status, _) = chat(&state, &key).await;
    assert_eq!(status, StatusCode::TOO_MANY_REQUESTS);

    let row = wait_for_row(&pool, |row| row.status == Some(429)).await;
    assert_eq!(
        row.api_key_id,
        Some(key_id),
        "the rejection row must name the key that hit its limit"
    );
    assert_eq!(row.channel_id, Some(channel_id));
    assert_eq!(row.model.as_deref(), Some(CHAT_MODEL));
    assert_eq!(row.error.as_deref(), Some("Monthly limit reached"));
}

/// Sends a chat request over the wire, so the flood gate sees a peer
/// address; `oneshot` requests carry none and would never be capped.
async fn post_chat_over_the_wire(base_url: &str, key: &str) -> reqwest::StatusCode {
    let response = within(
        reqwest::Client::new()
            .post(format!("{base_url}/v1/chat/completions"))
            .header("authorization", format!("Bearer {key}"))
            .header("content-type", "application/json")
            .body(json!({ "model": CHAT_MODEL, "messages": [] }).to_string())
            .send(),
    )
    .await
    .expect("request completes");
    let status = response.status();
    let _ = within(async { response.bytes().await }).await;
    status
}

#[tokio::test]
async fn a_limit_rejection_gives_its_flood_reservation_back() {
    let pool = test_pool().await;
    let channel_id = seed_limitable_channel(&pool, &upstream().await).await;
    let (key_id, key) = seed_limited_key(&pool, channel_id, Some(1)).await;
    // A budget of one: if the rejection settled as a failed authentication,
    // the second request would be flood-capped with a 401 instead.
    let state = test_app_with_flood(pool.clone(), 1, 60);
    log_usage_now(&pool, key_id, channel_id).await;
    recompute(&state, &pool, key_id).await;
    let base_url = spawn_hydra_with_connect_info(state).await;

    assert_eq!(
        post_chat_over_the_wire(&base_url, &key).await,
        reqwest::StatusCode::TOO_MANY_REQUESTS
    );
    assert_eq!(
        post_chat_over_the_wire(&base_url, &key).await,
        reqwest::StatusCode::TOO_MANY_REQUESTS,
        "the reservation must be released, not spent as a failed authentication"
    );
}
